from pathlib import Path
import json,hashlib,xml.etree.ElementTree as E,re,datetime
W=Path(__file__).resolve().parent;D=W/'sources/review-vv4126-vv4144-2026-10-20'
CARDS=[('KORE301222011','bgh-2011-ix-zr-153-10.md','BGH, Urteil vom 14. April 2011 – IX ZR 153/10','vv4141','''Gegenstand war der Anspruch gegen einen Rechtsschutzversicherer auf Freistellung von der zusätzlichen Gebühr nach Nr. 4141. Das Strafverfahren war in der Hauptverhandlung vorläufig gegen Auflage und nach deren Erfüllung endgültig eingestellt worden. Der BGH wies die Revision zurück: Die Gebühr war nicht entstanden.

Die tragenden eigenen Gründe stehen in Rn. 13–16. Der BGH unterscheidet die bloße Unterbrechung einer einheitlichen Hauptverhandlung von der Aussetzung mit später notwendiger neuer Hauptverhandlung. Die Erledigung innerhalb der laufenden Hauptverhandlung genügt auch dann nicht, wenn dadurch Fortsetzungstage entfallen. Nach Aussetzung kann die anwaltlich geförderte nicht nur vorläufige Einstellung dagegen eine neue Hauptverhandlung vermeiden. Die spätere endgültige Einstellung nach Erfüllung einer in der Hauptverhandlung auferlegten Auflage macht die Zusatzgebühr nicht allein nachträglich verdient.

Rn. 5 gibt die Begründung der Vorinstanz wieder; sie ist nicht als uneingeschränkter BGH-Satz zu verwenden, nach jeder früheren Hauptverhandlung sei die Gebühr für immer ausgeschlossen. Rn. 10–12 referieren konkurrierende Ansichten, von denen der BGH erst in Rn. 13 die differenzierende übernimmt. Die alten Geldbeträge werden nicht als aktueller Tarif verwendet. Der gegenwärtige Tatbestand enthält weitere Erledigungsvarianten; die Karte überträgt nur die weiterhin einschlägige Unterscheidung von laufender und neuer Hauptverhandlung. Keine vollständige Nachfolgerechtsprechungsrecherche.'''),('KORE310182011','bgh-2011-ix-zr-123-10.md','BGH, Urteil vom 20. Januar 2011 – IX ZR 123/10','vv4141','''Der Fall betrifft unmittelbar die Gebühr nach Nr. 5115 im Bußgeldverfahren. Ein Rechtsanwalt hatte seiner Mandantin zum Schweigen geraten und dies der Behörde mitgeteilt. Der Versicherer wandte ein, das Messfoto zeige zweifelsfrei einen männlichen Fahrer, sodass das Verfahren gegen die Mandantin unabhängig hiervon einzustellen gewesen sei. Der BGH hob das Berufungsurteil auf und verwies zur weiteren Tatsachenfeststellung zurück; er sprach die Gebühr nicht abschließend zu oder ab.

Rn. 7 verbindet die Regelungen der Nrn. 5115 und 4141 in ihrem gesetzgeberischen Grundgedanken. Rn. 8–9 verstehen Mitwirkung weit: Jede zur Förderung der Erledigung geeignete Tätigkeit kann genügen; eine besondere Sachaufklärung ist nicht verlangt. Der Rat zum Schweigen mit Mitteilung an die Behörde kann objektiv die Entscheidung fördern. Rn. 10 schließt die Gebühr hingegen aus, wenn die Einstellung wegen offenkundig fehlender Täterschaft unabhängig von der Einlassung ohnehin geboten ist. Ob das Foto diese Voraussetzung erfüllte, war noch festzustellen (Rn. 11).

Die Kommentierung von Nr. 4141 kennzeichnet die Anwendung dieses Förderungsmaßstabs als systematische Folgerung, gestützt auf die ausdrücklich vom Gericht hergestellte Parallele. Der Fall wird nicht als unmittelbare Entscheidung über den heutigen gesamten Tatbestand der Nr. 4141 ausgegeben. Er trägt keinen allgemeinen Satz, jeder bloße Einstellungsantrag genüge immer, und keinen strengen Alleinursächlichkeitsnachweis. Alte Gebührenbeträge werden nicht übernommen. Die im Text von Rn. 7 enthaltene abweichende Jahresangabe für die dort zitierte weitere Entscheidung wird nicht weiterverbreitet. Selektive Recherche, keine vollständige Folgenachweiskontrolle.'''),('KORE618082019','bgh-2018-3-str-625-17.md','BGH, Beschluss vom 29. November 2018 – 3 StR 625/17','vv4142','''Der Beschluss entscheidet über den Gegenstandswert der Verteidigertätigkeit im Revisionsverfahren. Angegriffen war ein Urteil mit Einziehung von insgesamt 18.681,95 Euro. Im Revisionsabschluss blieb nach teilweiser Einstellung beziehungsweise Beschränkung nur eine Einziehung von 8.116,60 Euro bestehen. Der BGH setzte den Gegenstandswert der auf die Einziehung bezogenen Tätigkeit dennoch auf 18.681,95 Euro fest.

Die eigenen Gründe in Rn. 4 bejahen die zusätzliche Wertgebühr für Tätigkeiten mit wenigstens auch vorhandenem Einziehungsbezug. Eine allgemeine Sachrüge der unbeschränkten Revision genügt in dieser Konstellation, weil sie das gesamte Urteil einschließlich der Einziehungsentscheidung zur Kontrolle stellt. Rn. 5 bestimmt den Wert nach dem wirtschaftlichen Interesse am Erfolg des Rechtsmittels, hier am Wegfall der ursprünglich insgesamt angeordneten Einziehung. Die zusätzlich entstehenden Gebühren für die Verteidigung gegen den Tatvorwurf stehen dem nicht entgegen.

Die Entscheidung betrifft weder jede beliebige Sicherstellung noch eine ausschließlich auf die Strafe beschränkte Revision. Sie ersetzt nicht die Prüfung des aktuellen Gegenstands, des Anfechtungsumfangs oder der Werttabelle. Die damalige Entscheidung ist bereits nach der Reform der Vermögensabschöpfung von 2017 ergangen; die aktuelle Kommentierung übernimmt den Tätigkeits- und Wertmaßstab, keine alten Tabellenbeträge oder inzwischen überholte Zuständigkeitsbesetzung. Keine erschöpfende Folgejudikaturrecherche.

Metadatenbefund: Der neu abgerufene amtliche XML-Datensatz nennt als Entscheidungsdatum 20181129, trägt aber die widersprüchliche ECLI-Zeichenfolge `ECLI:DE:BGH:2017:291117B3STR625.17.0`. Dieselbe Abweichung steht im nationalen Intake. Diese Metadaten werden unverändert gesichert; der Kommentar zitiert Datum und Aktenzeichen und verwendet den widersprüchlichen ECLI nicht als Datumsbeweis.'''),('KORE703612026','bgh-2026-5-str-524-25.md','BGH, Beschluss vom 28. Januar 2026 – 5 StR 524/25','vv4143, vv4144','''Die Revision war auf den Adhäsionsausspruch zugunsten eines einzelnen Anspruchstellers beschränkt (Rn. 1–2). Der Beschuldigte wandte sich unter anderem gegen die wirksame Zustellung des Adhäsionsantrags. Der BGH verwarf die Revision; die vom Gericht geprüfte Antragstellung und Zustellung waren wirksam.

Rn. 3–5 enthalten die eigenen tragenden Gründe zur Zustellung. Nach Rn. 4 umfasst die Pflichtverteidigerbestellung auch die Vertretung im Adhäsionsverfahren; deswegen konnte an den Pflichtverteidiger zugestellt werden. Der fünfte Strafsenat schließt sich ausdrücklich dieser Auffassung an und gibt seine gegenteilige eigene Rechtsprechung vom 8. Dezember 2021 – 5 StR 162/21 auf. Die Kommentierung darf die frühere Ablehnung daher am Stichtag Oktober 2026 nicht als unveränderte aktuelle Position dieses Senats darstellen.

Der Beschluss ist kein Gebührenfestsetzungsbeschluss. Die Folgerung für Nrn. 4143 und 4144 betrifft den Umfang der Bestellung; Tatbestand, Tätigkeit, Gegenstandswert, Höhe nach § 49 und weitere Voraussetzungen des Staatskassenanspruchs sind gesondert zu prüfen. Die Karte behauptet keine uneingeschränkte Zahlungspflicht für jede Position. Prozessuale Einzelheiten des Empfangsbekenntnisses werden nur als Fallkontext wiedergegeben, nicht als allgemeine Zustellungsanleitung. Die Entscheidung ist vor dem Manuskriptstichtag ergangen; die vollständigen amtlichen Gründe wurden mit dem lokalen nationalen Korpus verglichen. Keine vollständige Recherche zu sämtlichen Senaten, Folgeentscheidungen oder Festsetzungsfragen.

Datumskontrolle: Maßgeblich ist das im amtlichen Volltext und im ECLI belegte Datum 28. Januar 2026. Eine in der Suchrecherche erschienene sekundäre Angabe „26. Januar 2026“ wurde nicht übernommen.''')]
comparisons=[]
for k,fn,title,units,body in CARDS:
 r=E.parse(D/(k+'.xml')).getroot();local=(D/(k+'-intake.md')).read_text();ps=[]
 for sec in ['leitsatz','tenor','tatbestand','entscheidungsgruende','gruende']:
  for p in r.findall('.//'+sec+'//p'):
   t=''.join(p.itertext()).strip()
   if t:ps.append(t)
 missing=[p for p in ps if re.sub(r'\s+','',p) not in re.sub(r'\s+','',local)];assert ps and not missing
 comparisons.append(dict(doknr=k,judicial_paragraphs=len(ps),all_judicial_paragraphs_present_in_local_corpus=True,missing=[],official_xml_sha256=hashlib.sha256((D/(k+'.xml')).read_bytes()).hexdigest(),local_intake_sha256=hashlib.sha256((D/(k+'-intake.md')).read_bytes()).hexdigest()))
 text=f'# {title}\n\nGericht: Bundesgerichtshof. Unterstützte Einheiten: {units}. Volltext am 20. Oktober 2026 im amtlichen Neuabruf und nationalen lokalen Korpus gelesen.\n\n'+body+f'\n\n[Amtlicher Volltext](https://www.rechtsprechung-im-internet.de/jportal/?quelle=jlink&docid={k}); [gesicherte XML-Datei](../sources/review-vv4126-vv4144-2026-10-20/{k}.xml); [lokaler Korpusbeleg](../sources/review-vv4126-vv4144-2026-10-20/{k}-intake.md); [Abrufprotokoll und SHA-256](../sources/review-vv4126-vv4144-2026-10-20/authority-requests.json).\n\nEigene Zusammenfassung © 2026 Vojtěch Říha, Apache-2.0; amtlicher Entscheidungstext und gesicherte Quellen sind davon getrennt. Keine extern erteilte fachliche Freigabe.\n'
 (W/'cases'/fn).write_text(text)
(D/'case-source-comparison.json').write_text(json.dumps(comparisons,ensure_ascii=False,indent=2)+'\n')
print(comparisons)
